/// <summary>
/// Task 91522 : CB705_Rebate batch jobs & Vendor payback extension
/// </summary>
/// <returns>Check customer deal type validation</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();
    if (ret)
    {
        if ((TAMRebateDeal::find(this.RebateDeal).ModuleInventCustVend == ModuleInventCustVend::Cust) && TAMRebateDeal::find(this.RebateDeal).RebateReconciliation == TAMRebateReconciliation::Deal
            && this.METSkipPosting)
        {
            ret = checkFailed("@MET:ManualRebatePostingValidation");
        }
    }
    return ret;
}

/// <summary>
/// Get price attribute header details
/// </summary>
/// <returns>Price attribute header details</returns>
[SysClientCacheDataMethodAttribute(true)]
public display GUPPricingAttributeDetailsPreview metPricingAttributeDetailsHeader()
{
    GUPPricingAttributeDetailsPreview       retVal;

    retVal = this.pricingAttributeDetailsHeader();

    if (retVal != METConstants::emptyString)
    {
        retVal = this.getRebateConditionalVal(retVal);

        if (retVal == METConstants::emptyString)
        {
            retVal = METConstants::PriceAttributeHeader;
        }
    }
    else
    {
        retVal = METConstants::emptyString;
    }

    return retVal;
}

/// <summary>
