/// <summary>
/// Get rebate conditional value
/// </summary>
/// <param name = "_value">Value</param>
/// <returns>GUPPricingAttributeDetailsPreview</returns>
public GUPPricingAttributeDetailsPreview getRebateConditionalVal(GUPPricingAttributeDetailsPreview _value)
{
    GUPPricingAttributeDetailsPreview displayDetailsRetVal;

    container conDisplayDet = str2con(_value, METConstants::Semicolon);

    for (int i=1; i<=conLen(conDisplayDet); i++)
    {
        str       conStrVal              = conPeek(conDisplayDet, i);
        container conDisplayDetCondValue = str2con(conStrVal, METConstants::colon);

        if (conLen(conDisplayDetCondValue) == 2 &&
            strRTrim(conPeek(conDisplayDetCondValue, 2)) != METConstants::emptyString)
        {
            displayDetailsRetVal += strFmt(METConstants::DisplayCondVal, conStrVal);
        }
    }

    return strLRTrim(displayDetailsRetVal);
}

/// <summary>
/// While insert the <c>TAMRebateTable</c> record update pricing rule header information.
/// </summary>
public void insert()
{
    if (this.TAMRebateDeal().METVolumetricTierDeal == NoYes::Yes)
    {
        TAMRebateTable tamRebateTable;

        if (this.METTierLineType == METTierLineType::Value)
        {
            select firstonly tamRebateTable
                where tamRebateTable.METTierLineType == METTierLineType::Rate
                && tamRebateTable.RebateDeal == this.RebateDeal;

            if (tamRebateTable.PricingRuleHeader)
            {
                this.PricingRuleHeader = tamRebateTable.PricingRuleHeader;
                this.PriceComponentCombination = tamRebateTable.PriceComponentCombination;
            }
        }
        else
        {
            select firstonly forupdate tamRebateTable
                where tamRebateTable.METTierLineType == METTierLineType::Value
                && tamRebateTable.RebateDeal == this.RebateDeal;

            if (tamRebateTable.RecId && this.PricingRuleHeader)
            {
                ttsbegin;
                tamRebateTable.PriceComponentCombination = this.PriceComponentCombination;
                tamRebateTable.PricingRuleHeader = this.PricingRuleHeader;
                tamRebateTable.doUpdate();
                ttscommit;
            }
        }
    }

    next insert();

}

/// <summary>
/// While update the <c>TAMRebateTable</c> record update pricing rule header information.
/// </summary>
public void update()
{
    TAMRebateTable tamRebateTable;

    if (this.TAMRebateDeal().METVolumetricTierDeal == NoYes::Yes)
    {
        if (this.METTierLineType == METTierLineType::Rate)
        {
            select firstonly forupdate tamRebateTable
                where tamRebateTable.METTierLineType == METTierLineType::Value
                && tamRebateTable.RebateDeal == this.RebateDeal;

            if (tamRebateTable.RecId && this.PricingRuleHeader)
            {
                ttsbegin;
                tamRebateTable.PricingRuleHeader = this.PricingRuleHeader;
                tamRebateTable.PriceComponentCombination = this.PriceComponentCombination;
                tamRebateTable.doUpdate();
                ttscommit;
            }
        }
        else
        {
            select firstonly tamRebateTable
                where tamRebateTable.METTierLineType == METTierLineType::Rate
                && tamRebateTable.RebateDeal == this.RebateDeal;

            if (tamRebateTable.PricingRuleHeader)
            {
                this.PricingRuleHeader = tamRebateTable.PricingRuleHeader;
                this.PriceComponentCombination = tamRebateTable.PriceComponentCombination;
            }
        }
    }

    next update();

}
